INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('ab3d0f4b-63f6-501b-91e1-d146779e6e6e'::uuid, '7ea0ee24-7b79-5514-b425-c34c8a363506'::uuid, 'piscine semi-olympique Alhouda "AGADIR"', 'STE RAJELEC prend en charge le lot fluides et hydraulique de la piscine semi-olympique d’Ahouda, intégrant réseaux hydrauliques, systèmes de pompage, filtration et traitement d’eau, avec pour objectif d’assurer un ouvrage performant, sûr et durable.', '["https://lechantier.ma/uploads/media/21106afce736.webp", "https://lechantier.ma/uploads/media/22a2b7f336e2.webp", "https://lechantier.ma/uploads/media/06f71b423d68.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/21106afce736.webp', 'Tétouan', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
