INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d5d8542f-c4e0-5631-a561-5f401dcedc95'::uuid, '865b5236-ff5b-579a-9788-299db066b7db'::uuid, 'solaires', 'Notre projet agricole solaire repose sur l’installation d’un système photovoltaïque moderne destiné à alimenter les pompes à eau pour l’irrigation intelligente. Ce projet a permis de réduire les coûts en électricité et en carburant, tout en garantissant une énergie propre et durable qui améliore la productivité agricole et préserve l’environnement.', '["https://lechantier.ma/uploads/media/578e13ccf24c.webp", "https://lechantier.ma/uploads/media/7b5767142ed2.webp", "https://lechantier.ma/uploads/media/26e55bf1668a.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/578e13ccf24c.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('bb9cb51f-7d86-5462-996e-4dbccf6b9baf'::uuid, '865b5236-ff5b-579a-9788-299db066b7db'::uuid, 'piscines', 'Notre projet consiste en la conception et la réalisation d’une piscine moderne avec des standards de qualité élevés. Nous avons intégré les meilleures techniques de construction et d’étanchéité afin de garantir durabilité, sécurité et esthétique. Ce projet illustre notre engagement à offrir des espaces de détente alliant confort, élégance et innova', '["https://lechantier.ma/uploads/media/b43052fd7a9d.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/b43052fd7a9d.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
