INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a036b56a-c885-5f2a-8406-9dac43938cce'::uuid, 'd1c0ae2b-810d-52cf-8962-4fd413ac4ab0'::uuid, 'Système de dosage auto Pch Évolution', 'Fourniture et installation d''un système de dosage automatique PCH EVOLUTION ( spécial pour les piscines collective ) Le PCH Évolution permet d’automatiser la dilution des pastilles de chlore sans stabilisant (PCH) au fur et à mesure des besoins.', '["https://lechantier.ma/uploads/media/c6a4c7c8afed.webp", "https://lechantier.ma/uploads/media/a574f0801fd7.webp", "https://lechantier.ma/uploads/media/b52e78d08c08.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/c6a4c7c8afed.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '4.3.4' LIMIT 1));
